class Animal:
    def speak(self):
        return "?"

class Cat(Animal):
    def speak(self):
        return "meow"

class Dog(Animal):
    def speak(self):
        return "woof"

def collect_sounds(animals):
    sounds = []
    for animal in animals:
        sounds.append(animal.speak())
    return sounds

animals = [Cat(), Dog(), Cat()]
assert collect_sounds(animals) == ["meow", "woof", "meow"]
print("tests passed")

